/* ==========================================================================
   Hero scene art, lifted verbatim from the Route D prototype.

   These are hand-drawn SVG scenes: a gauge above its danger level in the
   rain, a sun over Titlagarh, a farmer with a phone at dawn, a field node on
   a pole. They animate through the classes in site.css (.rain, .live, .shim,
   .sunp, .vb, .ring, .led, .glint, .float) and sit behind a MEDots canvas.

   Stored as strings rather than JSX: this is our own static markup, and
   hand-converting several thousand attributes to camelCase would only add
   transcription errors.
   ========================================================================== */

export type SceneName =
  | 'thesisFailureModes'
  | 'thesisHazards'
  | 'floodRuleEngine'
  | 'floodAlertMap'
  | 'heatField'
  | 'heatObserved'
  | 'krishiTwoMouths'
  | 'bhoomiSpec'
  | 'bhoomiDataPath'
  | 'researchCurves'
  | 'researchGates'
  | 'aboutChain'
  | 'aboutShipped'
  | 'aboutTwoPeople'
  | 'deltaSplit' | 'deltaQuadrant' | 'flood' | 'heat' | 'krishi' | 'bhoomi' | 'thesis' | 'research' | 'about';

